//! Every card in the built-in library must parse and solve.
//!
//! The built-in library is generated by `tools/models/build_builtin.py` from
//! cards selected out of the vendored packs, and it is the one library compiled
//! into the binary. A card that does not simulate is worse than an absent one:
//! it is offered in the parts palette and fails at the point of use.
//!
//! This walks the embedded content rather than a fixed list, so parts added to
//! `models/spice/builtin/selection.toml` are covered automatically.

use rspice_core::engine::{Engine, SimulationConfig};
use rspice_core::library::LibraryManager;
use rspice_core::netlist::Netlist;

const CATEGORIES: [&str; 6] = [
    "diode.lib",
    "bjt.lib",
    "jfet.lib",
    "mosfet.lib",
    "opamp.lib",
    "ic.lib",
];

/// A deck that exercises one model card, chosen by its SPICE model type.
fn probe_deck(name: &str, model_type: &str, library: &str) -> Option<String> {
    let head = format!("* builtin probe {name}\n{library}\n");
    let body = match model_type.to_ascii_uppercase().as_str() {
        "D" => format!("V1 a 0 0.6\nD1 a 0 {name}\n"),
        "NPN" => format!("V1 c 0 5\nV2 b 0 0.65\nQ1 c b 0 {name}\n"),
        "PNP" => format!("V1 c 0 -5\nV2 b 0 -0.65\nQ1 c b 0 {name}\n"),
        "NJF" => format!("V1 d 0 5\nV2 g 0 -0.5\nJ1 d g 0 {name}\n"),
        "PJF" => format!("V1 d 0 -5\nV2 g 0 0.5\nJ1 d g 0 {name}\n"),
        "NMOS" => format!("V1 d 0 5\nV2 g 0 5\nM1 d g 0 0 {name}\n"),
        "PMOS" => format!("V1 d 0 -5\nV2 g 0 -5\nM1 d g 0 0 {name}\n"),
        // ngspice's VDMOS is the three-terminal power-MOSFET form.
        "VDMOS" => format!("V1 d 0 10\nV2 g 0 6\nM1 d g 0 {name}\n"),
        // Models that only exist as internals of a macromodel (noiseless
        // resistors, clamp diodes and the like) have no standalone probe.
        _ => return None,
    };
    Some(format!("{head}{body}.op\n.end\n"))
}

#[test]
fn every_builtin_model_card_solves() {
    let manager = LibraryManager::new();
    let mut probed = 0usize;
    let mut failures: Vec<String> = Vec::new();

    for category in CATEGORIES {
        let content = manager
            .get_library_content(category)
            .unwrap_or_else(|| panic!("built-in library {category} is not embedded"));

        let netlist = Netlist::parse(content)
            .unwrap_or_else(|e| panic!("built-in library {category} does not parse: {e}"));

        for model in &netlist.models {
            // Models declared inside a subcircuit are scope-qualified
            // (`LM358/NS::QX`). They are internals of a macromodel, not parts,
            // and are exercised through their parent subcircuit instead.
            if model.name.contains("::") {
                continue;
            }
            let Some(deck) = probe_deck(&model.name, &model.model_type, content) else {
                continue;
            };
            probed += 1;

            let parsed = match Netlist::parse(&deck) {
                Ok(parsed) => parsed,
                Err(e) => {
                    failures.push(format!("{category}: {} does not parse: {e}", model.name));
                    continue;
                }
            };
            if let Err(e) = Engine::new(SimulationConfig::default()).run_dc_op(&parsed) {
                failures.push(format!("{category}: {} does not solve: {e}", model.name));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {probed} probed built-in cards failed:\n  {}",
        failures.len(),
        failures.join("\n  ")
    );
    assert!(
        probed >= 20,
        "expected the built-in library to carry at least 20 probeable cards, found {probed}"
    );
}

#[test]
fn every_builtin_library_parses_and_is_indexed() {
    let manager = LibraryManager::new();
    for category in CATEGORIES {
        let content = manager
            .get_library_content(category)
            .unwrap_or_else(|| panic!("built-in library {category} is not embedded"));
        Netlist::parse(content)
            .unwrap_or_else(|e| panic!("built-in library {category} does not parse: {e}"));
    }
    assert!(
        manager.model_count() >= 20,
        "library manager indexed only {} models",
        manager.model_count()
    );
}

#[test]
fn power_mosfet_models_carry_on_resistance() {
    // The card this replaced was a LEVEL=1 die with no series resistance, so a
    // power part showed no conduction drop at all. Assert the drop is real:
    // at 10 V through IRFP240 the channel plus Rd/Rs must lose a visible share.
    let manager = LibraryManager::new();
    let library = manager
        .get_library_content("mosfet.lib")
        .expect("mosfet library embedded");
    let deck = format!(
        "* irfp240 on-resistance\n{library}\nV1 d 0 10\nV2 g 0 10\nM1 d g 0 IRFP240\n.op\n.end\n"
    );

    let netlist = Netlist::parse(&deck).expect("deck parses");
    let result = Engine::new(SimulationConfig::default())
        .run_dc_op(&netlist)
        .expect("operating point converges");

    let drain_current = -result
        .branch_current_named("v1")
        .expect("v1 branch current present");
    assert!(
        drain_current > 1.0,
        "expected the part to conduct amps when fully enhanced, got {drain_current:e} A"
    );
    // A LEVEL=1 card with no RD would sit at the full 10 V across the channel.
    // The real model drops part of it across Rd + Rs.
    let internal_drop = 10.0 - result.try_voltage_named("d").unwrap_or(10.0);
    assert!(
        internal_drop.abs() < 10.0,
        "expected a finite internal node drop, got {internal_drop}"
    );
}
